<script setup lang="ts">import MarketStateIcon from './MarketStateIcon.vue';import type {MarketHomeRow} from '@/utils/marketHomeViewModel';defineProps<{rows:MarketHomeRow[]}>();defineEmits<{open:[row:MarketHomeRow]}>();const alignment=(value:string)=>value.startsWith('aligned')?'aligned':value==='neutral'?'neutral':value==='unavailable'?'unavailable':null;const percentage=(value:number|null)=>value===null?'—':`${(value*100).toFixed(2)}%`</script>
<template><section class="mobile-list" aria-label="移动端品种列表"><button v-for="row in rows" :key="row.symbol" @click="$emit('open',row)"><strong>{{row.symbol.toUpperCase()}} {{row.product_name}}</strong><span>收盘 {{row.close}} · 1D {{percentage(row.price_change_1d)}}</span><i><b>日 <MarketStateIcon :state="row.dailyState"/></b><b>周 <MarketStateIcon :state="row.weeklyState"/></b><b>同向 <MarketStateIcon v-if="alignment(row.alignment)" :state="alignment(row.alignment)!"/><span v-else>未同向</span></b><b>HTDY {{row.event?'观察':'—'}}</b></i></button></section></template>
